def frame(inner, tag_text=''):
    """A compact comparison frame: 393 wide, paper, no tab bar."""
    return f'<div style="width: 393px; background: {PAPER}; {SANS} color: {INK}; box-sizing: border-box; padding-bottom: 22px; border: 1px solid rgba(27,23,20,0.06);">{inner}</div>'
def pair_cap(d, t, a_label, b_label, rec):
    return (f'<div style="display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px;"><div class="kick" style="color: {GOLDD};">{d}</div><div style="{SERIF} font-weight: 600; font-size: 22px; line-height: 28px;">{t}</div>'
            f'<div style="font-size: 13px; line-height: 19px; color: {INK2}; max-width: 840px;"><b>Recommendation:</b> {rec}</div></div>')
def side(label, fr, note):
    return f'<div style="width: 393px; flex: none; display: flex; flex-direction: column; gap: 8px;"><div class="kickm">{label}</div>{fr}<div class="fn" style="color: {ANCHOR}; line-height: 15px;">{note}</div></div>'
def pair(d, t, rec, a, b):
    return f'<div style="display: flex; flex-direction: column;">{pair_cap(d, t, "", "", rec)}<div style="display: flex; gap: 26px;">{a}{b}</div></div>'

# ───────────────────────────── D1 · openness ─────────────────────────────
def d1a():
    inner = f'<div style="padding: 24px 22px 0 22px;"><div class="kick" style="color: {GOLDD};">NATURAL LANGUAGE &middot; AUDIENCE ONLY</div></div>'
    inner += gut(f'<div style="border-radius: 12px; overflow: hidden;">{standin(150, "THE PASTA &middot; STAND-IN")}</div><div style="{SERIF} font-size: 18px; line-height: 25px; color: {INK}; margin-top: 10px;">Second try. Thinking of Saturday, if anyone&rsquo;s around.</div>' + meta('TO FRIENDS &middot; NO GUEST COUNT EXISTS', 8), top=14)
    inner += sect('What a friend sees') + gut(contribution('N', 'Nora', 'THURSDAY', 'Second try. Thinking of Saturday, if anyone&rsquo;s around.', scope='A LINE, NOT AN INVITATION &middot; REPLY IF YOU LIKE') + door('Reply to Nora'))
    inner += gut(src('Participation begins only when Nora sends the dinner (03.1) or a guest answers. &ldquo;Looks fun&rdquo; produces nothing.'), top=16)
    return frame(inner)
def d1b():
    inner = f'<div style="padding: 24px 22px 0 22px;"><div class="kick" style="color: {GOLDD};">ONE OPENNESS AFFORDANCE &middot; AUTHOR-CONTROLLED</div></div>'
    inner += gut(f'<div style="border-radius: 12px; overflow: hidden;">{standin(150, "THE PASTA &middot; STAND-IN")}</div><div style="{SERIF} font-size: 18px; line-height: 25px; color: {INK}; margin-top: 10px;">Second try.</div>'
                 + f'<div style="display: flex; align-items: center; gap: 10px; margin-top: 12px; padding: 10px 12px; border: 1px solid rgba(27,23,20,0.12); border-radius: 12px;"><span style="width: 34px; height: 20px; border-radius: 10px; background: {INK}; position: relative; flex: none;"><span style="position: absolute; right: 2px; top: 2px; width: 16px; height: 16px; border-radius: 8px; background: {CARD};"></span></span><span style="font-size: 14px; color: {INK};">Happy for company Saturday</span></div>' + meta('TO FRIENDS &middot; THE TOGGLE IS THE ONLY NEW STATE', 8), top=14)
    inner += sect('What a friend sees') + gut(contribution('N', 'Nora', 'THURSDAY', 'Second try.', scope='HAPPY FOR COMPANY SATURDAY &middot; SAY SO IF YOU&rsquo;D COME') + f'<div style="display: flex; gap: 18px;">{door("I&rsquo;d come")}{door("Reply to Nora")}</div>')
    inner += gut(src('&ldquo;I&rsquo;d come&rdquo; is a request; Nora still decides and sends. The cost: a second state to explain, and a request that can be ignored in silence.'), top=16)
    return frame(inner)

