def maya_return_min(ack=False):
    inner = header('Yours', 'Thursday &middot; to friends &middot; through Sunday', back=True)
    inner += gut(f'<div style="{SERIF} font-size: 20px; line-height: 27px; color: {INK};">{by("Maya", "print_room")[2]}</div>', top=14)
    if ack:
        inner += sect('From friends') + gut('<div>' + arow('Nora &middot; <span style="color: #6E6862;">lovely</span>', avatars=['N']) + arow('Nora &middot; That side room. I want to see it before Sunday.', avatars=['N'], last=True) + '</div>' + meta('ONE WORD, HERS TO CHOOSE, SEEN ONLY BY MAYA &middot; NO COUNT', 8))
    else:
        inner += sect('A reply') + gut('<div>' + arow('Nora &middot; That side room. I want to see it before Sunday.', avatars=['N'], last=True) + '</div>' + meta('A REPLY, IF ONE COMES &middot; NOTHING ELSE', 8))
    inner += gut(f'<div style="display: flex; gap: 22px;">{door("Edit")}{door("Take it back", MUTE)}</div>', top=20)
    return frame(inner)

