def route_row(who, steps):
    rc, rb = ROLE[who]
    boxes = []
    for i, (n, t, root) in enumerate(steps):
        boxes.append(f'<div style="width: 150px; flex: none; border: 1px solid rgba(27,23,20,0.10); background: {CARD}; border-radius: 8px; padding: 10px 12px; display: flex; flex-direction: column; gap: 4px;"><div style="display: flex; gap: 6px; align-items: center;"><span style="{MONO} font-size: 10px; font-weight: 700; color: {MUTE};">{n}</span>{tag(root, MUTE, "rgba(27,23,20,0.06)")}</div><div style="font-size: 12.5px; line-height: 17px; color: {INK};">{t}</div></div>')
        if i < len(steps) - 1: boxes.append(f'<div style="flex: none; align-self: center; color: {GHOST};">{ARROW}</div>')
    return (f'<div style="display: flex; flex-direction: column; gap: 10px; margin-top: 22px;"><div style="display: flex; gap: 8px; align-items: center;">{tag(who, rc, rb)}<span class="fn" style="color: {ANCHOR};">FOLLOW WITHOUT READING ANYONE ELSE&rsquo;S PRIVATE CONTEXT</span></div>'
            f'<div style="display: flex; gap: 8px; align-items: stretch; flex-wrap: wrap;">' + ''.join(boxes) + '</div></div>')
def board06():
    inner = blk('ONE ROUTE PER PARTICIPANT &middot; LINKED FRAMES', ''.join(route_row(w, s) for w, s in ROUTES.items()))
